int generate_random_k(WC_RNG* rng, int size, mp_int* k, mp_int* order) {
    int ret = 0;
    byte* randomBytes = NULL;
    mp_int max, temp;

    // Allocate memory for the random bytes
    randomBytes = (byte*)malloc(size);
    if (!randomBytes) {
        return MEMORY_E;
    }

    // Generate random bytes
    ret = wc_RNG_GenerateBlock(rng, randomBytes, size);
    if (ret != 0) {
        free(randomBytes);
        return ret;
    }

    // Initialize and convert random bytes to an integer
    mp_init(&max);
    mp_init(&temp);
    mp_read_unsigned_octet(&max, randomBytes, size);

    // Ensure the generated value is less than the order
    if (mp_cmp(&max, order) >= 0) {
        mp_init_copy(&temp, order);
        mp_sub_d(&temp, 1, &temp); // k_max = order - 1
        mp_copy(&temp, &max);
    }

    // Ensure k is not zero
    if (mp_cmp_d(&max, 0) == 0) {
        mp_set_int(&max, 1);
    }

    // Assign result to k
    mp_copy(&max, k);

    // Clean up
    mp_clear(&max);
    mp_clear(&temp);
    free(randomBytes);

    return ret;
}

int wc_GenerateECCRandomK(WC_RNG* rng, int size, mp_int* k, mp_int* order) {
    int ret = 0;
    byte* randBytes = NULL;
    int randSz = size;
    int i;

    if (rng == NULL || k == NULL || order == NULL || size <= 0) {
        return BAD_FUNC_ARG;
    }

    randBytes = (byte*)XMALLOC(randSz, 0);
    if (randBytes == NULL) {
        return MEMORY_E;
    }

    ret = wc_RNG_GenerateBlock(rng, randBytes, randSz);
    if (ret != 0) {
        XFREE(randBytes, 0);
        return ret;
    }

    mp_init(k);
    mp_read_unsigned_bin(k, randBytes, randSz);

    XFREE(randBytes, 0);

    if (mp_cmp(k, order) >= 0) {
        return RNG_FAILURE_E;
    }

    if (mp_cmp_d(k, 0) == 0) {
        for (i = 0; i < randSz; i++) {
            if (randBytes[i] != 0) {
                break;
            }
        }
        if (i == randSz) {
            return RNG_FAILURE_E;
        }
    }

    return 0;
}

int wc_ecc_make_rand_mp_int(WC_RNG* rng, int size, mp_int* k, mp_int* order) {
    int ret = 0;
    unsigned char* bytes = NULL;
    mp_int temp;

    if (rng == NULL || k == NULL || order == NULL || size <= 0)
        return BAD_FUNC_ARG;

    if ((bytes = (unsigned char*)XMALLOC(size, NULL, DYNAMIC_TYPE_TMP_BUFFER)) == NULL)
        return MEMORY_E;

    if (wc_RNG_Generate_Block(rng, bytes, size) != 0) {
        ret = RNG_FAILURE_E;
        goto cleanup;
    }

    mp_init(&temp);
    mp_read_unsigned_bin(&temp, bytes, size);

    if (mp_cmp(&temp, order) >= 0 || mp_cmp_d(&temp, 0) == 0) {
        // Ensure k is less than order and not zero
        mp_sub_d(&temp, 1, &temp);
        if (mp_cmp_d(&temp, 0) == 0)
            mp_set_int(&temp, 1);
    }

    mp_exch(&temp, k);

cleanup:
    if (bytes != NULL)
        XFREE(bytes, NULL, DYNAMIC_TYPE_TMP_BUFFER);
    mp_clear(&temp);
    return ret;
}

int wc_GenerateRandomK(WC_RNG* rng, int size, mp_int* k, mp_int* order) {
    int ret = 0;
    byte* buf = NULL;
    mp_int temp;

    if (rng == NULL || k == NULL || order == NULL) {
        return BAD_FUNC_ARG;
    }

    mp_init(&temp);

    buf = (byte*)XMALLOC(size, HEAP_HINT, DYNAMIC_TYPE_TMP_BUFFER);
    if (buf == NULL) {
        mp_clear(&temp);
        return MEMORY_E;
    }

    if ((ret = wc_RNG_GenerateBlock(rng, buf, size)) != 0) {
        XFREE(buf, HEAP_HINT);
        mp_clear(&temp);
        return ret;
    }

    if ((ret = mp_read_radix(&temp, (char*)buf, 16)) != 0) {
        XFREE(buf, HEAP_HINT);
        mp_clear(&temp);
        return ret;
    }

    while (1) {
        if ((ret = mp_cmp_mag(&temp, order)) == 1) {
            if ((ret = mp_div_2(&temp, &temp)) != 0)
                break;
        } else {
            if ((ret = mp_copy(&temp, k)) != 0)
                break;
            break;
        }
    }

    XFREE(buf, HEAP_HINT);
    mp_clear(&temp);

    if (ret != 0)
        return ret;

    if (mp_cmp_d(k, 0) == MP_EQ) {
        if ((ret = wc_GenerateRandomK(rng, size, k, order)) != 0)
            return ret;
    }

    return 0;
}

#include <wolfssl/wolfcrypt/integer.h>
#include <wolfssl/wolfcrypt/rng.h>

int generate_random_k(WC_RNG* rng, int size, mp_int* k, mp_int* order) {
    int ret;
    byte* randomBytes = (byte*)XMALLOC(size, NULL, DYNAMIC_TYPE_TMP_BUFFER);
    if (!randomBytes) {
        return MEMORY_E;
    }

    WC_RNG_GenerateBlock(rng, randomBytes, size);

    mp_unsigned_bin_ui_to_mp(randomBytes, size, k);

    // Ensure k is less than order
    if (mp_cmp(k, order) >= 0) {
        mp_div(k, order, k, NULL);
    }

    // Ensure k is not zero
    if (mp_cmp_d(k, 0) == 0) {
        mp_set_int(k, 1);
    }

    XFREE(randomBytes, NULL, DYNAMIC_TYPE_TMP_BUFFER);
    return ret;
}
